package org.eclipse.rdf4j.tools.serverboot;

final class OutOfMemoryErrorSupport {

	private OutOfMemoryErrorSupport() {
	}

	/**
	 * Finds an out-of-memory error in a throwable cause chain without allocating or imposing a depth limit.
	 *
	 * <p>
	 * Cause chains are normally acyclic, but a custom throwable can contain a cycle. Floyd's tortoise-and-hare walk
	 * keeps this emergency path bounded for both ordinary deep wrappers and malformed cyclic chains.
	 * </p>
	 */
	static OutOfMemoryError find(Throwable root) {
		Throwable slow = root;
		Throwable fast = root;
		while (slow != null) {
			if (slow instanceof OutOfMemoryError outOfMemoryError) {
				return outOfMemoryError;
			}
			slow = next(slow);
			if (slow == null) {
				return null;
			}

			fast = next(next(fast));
			if (slow == fast) {
				// The meeting point is arbitrary. Walk the complete cycle before declaring that no OOM exists; a
				// tortoise-and-hare meeting can occur before a later cycle node that contains the error.
				Throwable cycle = slow;
				do {
					if (cycle instanceof OutOfMemoryError outOfMemoryError) {
						return outOfMemoryError;
					}
					cycle = next(cycle);
				} while (cycle != slow);
				return null;
			}
		}
		return null;
	}

	private static Throwable next(Throwable throwable) {
		return throwable == null ? null : throwable.getCause();
	}
}
